{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "Initial data from independent evaluations suggest that the performance of SARS-CoV-2 Ag-RDTs may be lower than what is reported by the manufacturers. In addition, Ag-RDT accuracy seems to vary substantially between tests [4-6]. ... Such evaluations differ widely in their quality, methods, and results, making it difficult to assess the true performance of the respective tests [7].",
      "reason": "The Introduction describes the current state of knowledge (growing number of Ag-RDTs, independent evaluations showing lower and variable performance) and highlights the uncertainty caused by heterogeneous evaluation quality."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "To inform decision makers on the best choice of individual tests, an aggregated, widely available, and frequently updated assessment of the quality, performance, and independence of the data is urgently needed.",
      "reason": "The need and importance of the review are explicitly stated, supported also by the Author Summary (text_4): 'To inform decision makers about the best test to choose, an up-to-date summary of their performance is needed.'"
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "While other systematic reviews have been published, they include data only up until November 2020 [8-11], exclude preprints [12], or were industry sponsored [13]. In addition, only 1 assessed the quality of studies in detail, with data up until November 2020 [7,11].",
      "reason": "Existing systematic reviews are identified and cited, and the need for the current review (more recent, living, non-industry-sponsored, including preprints) is explained: 'we aim to close this gap in the literature'."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a diagnostic accuracy review, not a review of intervention effects; no mechanism-of-action description is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Not a review of complex interventions or delivery contexts; a logic model is not applicable to diagnostic test accuracy."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "In this systematic review and meta-analysis, we assessed the clinical accuracy (sensitivity and specificity) of commercially available Ag-RDTs.",
      "reason": "The abstract explicitly states the review objective (assessing clinical accuracy of commercially available Ag-RDTs), and the Introduction (text_7) reinforces the aim: 'With our systematic review and meta-analysis, we aim to close this gap in the literature...'. While not framed in a formal framework like PICO, the objective/question is clearly and explicitly stated."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a diagnostic accuracy review, not a review of intervention effects; PICO-style planned comparisons do not apply. The review assesses sensitivity and specificity of Ag-RDTs against a reference standard, as stated in text_1."
    }
  ],
  "confidence": 90
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Weincluded studies evaluating the accuracy of commercially available Ag-RDTs to establish a diagnosis of SARS-CoV-2 infection, against reverse transcription polymerase chain reaction (RT-PCR) or cell culture as reference standard. We included all study populations irrespective of age, presence of symptoms, or study location. We considered cohort studies, nested cohort studies, case-control or cross-sectional studies, and randomized studies.",
      "reason": "Index test, reference standard, populations, settings, and eligible study designs are all explicitly specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_10",
      "quote": "We included both peer-reviewed publications and preprints.",
      "reason": "Publication status (peer-reviewed vs preprints) is specified, but no explicit restrictions on dissemination year or language of publications are stated in the eligibility criteria."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "PARTIAL",
      "chunk_id": "text_19",
      "quote": "Reports excluded: Ag-RDT not commercially available (n = 34), Guidelines, reviews, modelling (n = 33), Monitoring (n = 24), Use case not diagnosis (n = 20), No estimation of sens. and spec. (n = 14), Did not assess an Ag-RDT (n = 12)...",
      "reason": "The PRISMA flow diagram lists 'No estimation of sens. and spec.' as an exclusion reason, which is suggestive but does not explicitly distinguish between outcomes not measured versus outcome results not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_14",
      "quote": "Wedifferentiated between clinical accuracy studies (performed on clinical samples) and analytical accuracy studies (performed on spiked samples with a known quantity of virus)... we only considered data from clinical accuracy studies as eligible for the meta-analysis. Separately, we summarized the results of analytical studies and compared them with the results of the meta-analysis for individual tests.",
      "reason": "Groups for each synthesis (clinical vs analytical accuracy datasets, with further subgroup/sensitivity analyses) are clearly specified and linked to the review's accuracy comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_10",
      "quote": "Also, publications with a population size smaller than 10 were excluded. Although the size threshold of 10 is arbitrary, such small studies are more likely to give unreliable estimates of sensitivity and specificity.",
      "reason": "A rationale is explicitly provided for the notable minimum population size restriction."
    }
  ],
  "confidence": 90
}

